4	 * Computes an owner's {@code checkDigit} — a single Luhn check digit (0-9) over the digits
5	 * contained in the owner's {@code customerCode}. Non-digit characters (e.g. the {@code '-'}
6	 * separators and letter prefixes) are ignored.
7	 *
8	 * <p>Standard Luhn: working right-to-left, every second digit starting from the rightmost is
9	 * doubled (subtracting 9 when the result exceeds 9); the check digit is the amount needed to
10	 * bring the running total to the next multiple of ten.
11	 */
12	public final class CustomerCodeCheckDigit {
13	
14	    private CustomerCodeCheckDigit() {
15	    }
16	
17	    /** The Luhn check digit (0-9) over the digits in {@code customerCode}. */
18	    public static int of(String customerCode) {
19	        int sum = 0;
20	        boolean doubleDigit = true;
21	        for (int i = customerCode.length() - 1; i >= 0; i--) {
22	            char c = customerCode.charAt(i);
23	            if (c < '0' || c > '9') {
24	                continue;
25	            }
26	            int d = c - '0';
27	            if (doubleDigit) {
28	                d *= 2;
29	                if (d > 9) {
30	                    d -= 9;
31	                }
32	            }
33	            sum += d;
34	            doubleDigit = !doubleDigit;
35	        }
36	        return (10 - (sum % 10)) % 10;
